    if abs(runner["overlap"] - 1.0) > 1e-9:
        fails.append(f"runner self-score overlap: {runner['overlap']}")
    agree = scorer_agreement(runner, indep)
    if not agree["ok"]:
        fails.append(f"scorers disagree on the self-score: {agree}")
